class RideSharingSystem {
    queue<int> riders, drivers;
    unordered_set<int> cancelled;
public:
    RideSharingSystem() {}
    void addRider(int riderId) { riders.push(riderId); }
    void addDriver(int driverId) { drivers.push(driverId); }
    vector<int> matchDriverWithRider() {
        while (!riders.empty() && cancelled.count(riders.front())) riders.pop();
        if (riders.empty() || drivers.empty()) return {-1, -1};
        int d = drivers.front(); drivers.pop();
        int r = riders.front(); riders.pop();
        return {d, r};
    }
    void cancelRider(int riderId) { cancelled.insert(riderId); }
};

