class RideSharingSystem {
    private Deque<Integer> riders = new ArrayDeque<>();
    private Deque<Integer> drivers = new ArrayDeque<>();
    private Set<Integer> cancelled = new HashSet<>();
    public void addRider(int riderId) { riders.addLast(riderId); }
    public void addDriver(int driverId) { drivers.addLast(driverId); }
    public int[] matchDriverWithRider() {
        while (!riders.isEmpty() && cancelled.contains(riders.peekFirst())) riders.pollFirst();
        if (riders.isEmpty() || drivers.isEmpty()) return new int[]{-1, -1};
        return new int[]{drivers.pollFirst(), riders.pollFirst()};
    }
    public void cancelRider(int riderId) { cancelled.add(riderId); }
}

