class RideSharingSystem {
    vector<int> riderOrder, driverOrder;
    unordered_map<int,int> status; // 0 waiting, 1 matched/cancelled
    size_t ri = 0, di = 0;
public:
    void addRider(int riderId) { riderOrder.push_back(riderId); status[riderId] = 0; }
    void addDriver(int driverId) { driverOrder.push_back(driverId); }
    vector<int> matchDriverWithRider() {
        while (ri < riderOrder.size() && status[riderOrder[ri]] != 0) ri++;
        if (ri >= riderOrder.size() || di >= driverOrder.size()) return {-1, -1};
        int r = riderOrder[ri++]; status[r] = 1;
        return {driverOrder[di++], r};
    }
    void cancelRider(int riderId) { if (status.count(riderId) && status[riderId] == 0) status[riderId] = 1; }
};

