class RideSharingSystem {
    private List<Integer> riderOrder = new ArrayList<>(), driverOrder = new ArrayList<>();
    private Map<Integer, Boolean> waiting = new HashMap<>();
    private int ri = 0, di = 0;
    public void addRider(int riderId) { riderOrder.add(riderId); waiting.put(riderId, true); }
    public void addDriver(int driverId) { driverOrder.add(driverId); }
    public int[] matchDriverWithRider() {
        while (ri < riderOrder.size() && !waiting.get(riderOrder.get(ri))) ri++;
        if (ri >= riderOrder.size() || di >= driverOrder.size()) return new int[]{-1, -1};
        int r = riderOrder.get(ri++); waiting.put(r, false);
        return new int[]{driverOrder.get(di++), r};
    }
    public void cancelRider(int riderId) { waiting.replace(riderId, false); }
}

